const body = $json;
if (!body.legal_entity_id) throw new Error('Missing legal_entity_id');
const attendees = body.attendees || [];
const valid = attendees.filter(a => !!a.email || !!a.name);
const invalid = attendees.filter(a => !a.email && !a.name);
return [{json: {valid, invalid, legal_entity_id: body.legal_entity_id}}];
